def tau(n):
    if n == 1:
        return 1
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return 1

def check_condition(n):
    # We need tau(n^12)

    # Find prime factorization of n
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Calculate tau(n^12)
    # If n = p1^a1 * p2^a2 * ..., n^12 = p1^(12*a1) * p2^(12*a2) * ...
    tau_n_12 = 1
    for exponent in factors.values():
        tau_n_12 *= (12 * exponent + 1)

    return tau_n_12 == n

solutions = [13, 25, 325]

print("Checking solutions:")
for n in solutions:
    is_solution = check_condition(n)
    print(f"n={n}: Is solution? {is_solution}")
